/* Mächte aus dem Horror-Kompendium (HOR) */
(function(){
var H = SW_MH;
H.ah([{"id": "hor_alch", "n": "Alchemist (Horror)", "s": ["HOR"], "req": "Verstand W6+", "f": "Alchemie (Verstand)", "sm": "3 beliebige aus der Liste", "mp": "15", "av": ["Verbannen", "Tierfreund", "Flächenschlag", "Blenden", "Eigenschaft erhöhen/senken", "Strahl", "Verwirrung", "Dunkelsicht", "Abwehren", "Arkanes entdecken/verbergen", "Empathie", "Verstricken", "Schutz vor Naturgewalten", "Fernsicht", "Furcht", "Fliegen", "Wachsen/Schrumpfen", "Heilung", "Unberührbarkeit", "Unsichtbarkeit", "Licht/Dunkelheit", "Schutz", "Marionette", "Linderung", "Wiederauferstehung", "Gestaltwandeln", "Trägheit/Beschleunigung", "Schlummer", "Waffe verbessern", "Sprachen sprechen", "Wandkrabbler", "Kriegersegen"], "sp": [["Machtedges", "Alchemisten dürfen nur die Machttalente Artefakterschaffer, Neue Mächte, Machtpunkte und Talente nehmen, die ausdrücklich für den Arkanen Hintergrund (Alchemist) genannt werden."], ["Machtmodifikatoren", "Alchemisten dürfen den Machtmodifikator Selektiv nicht verwenden."], ["Alchemistenbeutel", "Die Gebräue und die Zutaten, die Alchemisten zu ihrer Herstellung brauchen, werden in einer Art Beutel aufbewahrt. Solange die Alchemistin Zugriff auf ihren Beutel hat, kann sie auch Alchemistische Gegenstände herstellen (siehe S. 99)."], ["Komponenten", "Pillen, Tränke und Granaten der Alchemisten sind Verbrauchsgüter und geben ihnen das Handicap Materialkomponenten."], ["Aktivierung", "Wenn eine Alchemistin eine Macht „wirkt“, muss der Spieler beschreiben, wie sie verabreicht wird. Mächte mit der Reichweite Selbst oder Berührung sind meist ein Trank, Essbares, eine Pille, Salbe oder ein Öl. Die Erschöpfung durch einen Kritischen Fehlschlag trifft den Empfänger, wenn es nicht die Alchemistin selbst ist. Mächte mit größerer Reichweite nutzen Zerstäuber, Blasebälge oder Granaten mit einer maximalen Reichweite von 12“ (24 Meter). Die Alchemistin „wirft“ die Granate oder bedient den Zerstäuber mit Alchemie statt Athletik oder Schießen (andere Geschosse werden normal behandelt). Ein Kritischer Fehlschlag trifft die Wirkerin normal – das Gerät zerspringt in ihrer Hand und hüllt sie in giftige Dämpfe, die Erschöpfung verursachen."], ["Gebräue an andere weitergeben", "Eine Alchemistin kann ihr Gebräu wie jede andere Macht an nahe Verbündete „verabreichen“. Will sie jemandem ein Gebräu zum späteren Gebrauch mitgeben, legt sie die Macht fest und investiert eine beliebige Zahl ihrer aktuellen Machtpunkte. Weitergegebene Gebräue haben einen bestimmten Aspekt – Eigenschaft erhöhen (Stärke) zum Beispiel, oder Trägheit (aber nicht Beschleunigung). Die Alchemistin hat dabei keine Wahl; sie kann Eigenschaft erhöhen nicht ohne Nennung der Eigenschaft weitergeben, auch wenn die Macht normalerweise keine Aspekt-Einschränkung hat. Weitergegebene Gebräue halten, bis sie verbraucht werden oder 48 Stunden vergangen sind, je nachdem, was zuerst eintritt. Sobald ihre Machtpunkte verbraucht sind, erhält die Alchemistin sie normal zurück. Der Empfänger würfelt mit der Alchemie des Herstellers, als würde die Alchemistin es selbst verabreichen."]], "b": ["Alchemisten stellen Tränke, Öle, Elixiere und andere Verbrauchsgüter her, die mit den Mächten erfüllt sind, die sie gelernt haben. Erzählerisch entstehen ihre Gebräue „außerhalb der Kamera“ schon vor dem Gebrauch. Spieltechnisch werden sie „gewirkt“, wenn der Spieler sie braucht – indem Fläschchen oder Behälter aus dem Alchemistenbeutel oder Bandelier gezogen und aktiviert werden."], "p": 56}, {"id": "hor_blig", "n": "Gezeichneter", "s": ["HOR"], "req": "Willenskraft W6+", "f": "Fokus (Willenskraft)", "sm": "Zwei beliebige, die angesichts des Ursprungs der Macht Sinn ergeben", "mp": "15", "av": [], "sp": [["Favorisierte Macht", "Gezeichnete wählen eine ihrer Startmächte und dürfen beim Aktivieren dieser Macht bis zu 2 Punkte beliebiger Abzüge (Mehrfachaktion, Wunden, Erschöpfung usw.) ignorieren."], ["Macht", "Gezeichnete dürfen Talente nehmen, die einen beliebigen Arkanen Hintergrund voraussetzen, ignorieren dabei die Voraussetzung „Arkaner Hintergrund“ und ersetzen jede Voraussetzung einer arkanen Fertigkeit durch Fokus."], ["Verderbnis", "Gezeichnete erhielten ihre Fähigkeiten von mächtigen übernatürlichen Quellen. Selbst wenn die Quelle grundsätzlich gut war, ist diese Art von Macht für Sterbliche schwer zu begreifen und zu beherrschen. Sie haben das Handicap Verderbnis (S. 6)."]], "b": ["Manchmal begegnet ein Sterblicher einer übernatürlichen Macht, die so stark ist, dass sie seine Seele verdirbt – ihm aber im Gegenzug einen Bruchteil ihrer Kraft schenkt. Oder er ist selbst das Kind eines abscheulichen oder unglaublichen wissenschaftlichen Experiments, der gotteslästerlichen Verbindung von Sterblichem und Übernatürlichem oder eines Ausläufers einer bizarren Entwicklungslinie.", "Die Quelle bestimmt die Natur der Fähigkeiten der Gezeichneten, daher stehen alle Mächte zur Verfügung, solange Spieler und SL finden, dass sie zum Thema des Ursprungs passen.", "Die Gezeichneten haben viele Ursprünge. Manche waren buchstäblich in der Hölle und kehrten befleckt zurück. Eine andere hat die wahre Gestalt eines Engels gesehen und ihre Seele für immer verändert gefunden. Wieder andere haben Tier-DNA, das Blut von Monstern in sich oder sind selbst Produkte verrückter Wissenschaft oder Zauberei.", "Weil ihre Ursprünge so vielfältig sind, haben Gezeichnete keine eigenen Talente, können aber die jedes anderen Arkanen Hintergrunds nehmen, ignorieren die Voraussetzung „Arkaner Hintergrund“ und ersetzen jede Voraussetzung einer arkanen Fertigkeit durch Fokus. Andere Voraussetzungen müssen wie üblich erfüllt werden."], "p": 57}, {"id": "hor_daem", "n": "Dämonologe", "s": ["HOR"], "req": "Verstand W6+", "f": "Zaubern (Verstand)", "sm": "Verbannen, Chaos, Verbündeten beschwören und zwei weitere Mächte aus der Liste (Verbannen darf schon im Rang Anfänger genutzt werden)", "mp": "10", "av": ["Arkaner Schutz", "Verbannen", "Barriere", "Flächenschlag", "Geschoss", "Strahl", "Boden weihen", "Fluch", "Schadensfeld", "Dunkelsicht", "Arkanes entdecken/verbergen", "Aufheben", "Zwiesprache", "Machtpunkte entziehen", "Schutz vor Naturgewalten", "Exorzismus", "Furcht", "Chaos", "Illusion", "Trugschrecken", "Licht/Dunkelheit", "Albträume", "Marionette", "Seance", "Waffe verbessern", "Sprachen sprechen", "Rachsucht", "Verbündeten beschwören", "Dämon beschwören", "Wandkrabbler"], "sp": [["Magie", "Dämonologen dürfen Talente nehmen, die den Arkanen Hintergrund (Magie) voraussetzen."], ["Verderbnis", "Dämonologen verkehren mit außerweltlichen Wesenheiten, meist bösen oder zumindest verspielten. Sie haben das Handicap Verderbnis (S. 6)."], ["Beschwörung", "Dämonologen dürfen mit Verbündeten beschwören bereits im Rang Anfänger Dämonenlegionäre (S. 118) für 4 Machtpunkte rufen. Im Rang Fortgeschritten dürfen sie Höllenhunde (S. 120) für 5 Punkte herbeirufen, im Rang Veteran ein Dämonenross (S. 119) für 7 Punkte."]], "b": ["Wer Dämonen studiert, jagt, beschwört und mit ihnen verkehrt, ist ein mächtiger Held, spielt aber mit gefährlichen Kräften."], "p": 58}, {"id": "hor_wahr", "n": "Wahrsagerin", "s": ["HOR"], "req": "Verstand W6+", "f": "Zaubern (Verstand)", "sm": "Zwei beliebige aus der Liste", "mp": "15", "av": ["Dunkelsicht", "Abwehren", "Arkanes entdecken/verbergen", "Zwiesprache", "Empathie", "Fernsicht", "Orten", "Objekt auslesen", "Schutz", "Fernschau", "Seance"], "sp": [["Magie", "Wahrsagerinnen dürfen Talente nehmen, die den Arkanen Hintergrund (Magie) voraussetzen."], ["Das Zweite Gesicht", "Nachdem alle Aktionskarten ausgeteilt und aufgelöst wurden, kann eine Wahrsagerin einen Benny ausgeben, um die Aktionskarten aller willigen Verbündeten einzusammeln und nach Belieben neu zu verteilen."]], "b": ["Manche nennen es „das Zweite Gesicht“. Andere träumen von Szenen oder Bildern, die schließlich wahr werden. Einige versuchen aktiv, in die Zukunft zu blicken, vielleicht mit Kristallkugeln, Tarotkarten, Teeblättern oder weniger angenehmen Hilfsmitteln.", "Wahrsagerinnen sind auf Weissagung und das Sprechen mit Geistern spezialisiert. Sie sind Leitungen zu einer Welt, die die meisten Sterblichen nicht sehen. Sie haben im Vergleich zu den meisten, die sich mit den arkanen Künsten befassen, nur sehr wenige Zauber, aber auch weniger Nachteile."], "p": 60}, {"id": "hor_medi", "n": "Medium", "s": ["HOR"], "req": "Willenskraft W6+", "f": "Zaubern (Verstand)", "sm": "Verbannen, Arkanes entdecken/verbergen und eine beliebige weitere Macht aus der Liste (Verbannen darf schon im Rang Anfänger genutzt werden)", "mp": "15", "av": ["Arkaner Schutz", "Verbannen", "Tierfreund", "Boden weihen", "Leichensinn", "Dunkelsicht", "Arkanes entdecken/verbergen", "Aufheben", "Zwiesprache", "Empathie", "Exorzismus", "Grabtuch", "Orten", "Objekt auslesen", "Zuflucht", "Fernschau", "Seance", "Sprachen sprechen"], "sp": [["Magie", "Medien dürfen Talente nehmen, die den Arkanen Hintergrund (Magie) voraussetzen."], ["Ich sehe tote Menschen", "Medien spüren unkörperliche und unsichtbare Kreaturen. Sie handeln immer so, als stünden sie unter der Wirkung von Arkanes entdecken, und würfeln ihre arkane Fertigkeit nur, wenn sie versuchen, durch Arkanes verbergen oder ähnliche Verschleierungen hindurchzusehen."]], "b": ["Es ist ebenso Fluch wie Segen, die Geisterwelt zu sehen und mit ihr zu sprechen. Feen können launisch, eifersüchtig und grausam sein. Dämonen sind verruchte Lügner und Betrüger. Und die Toten sind unerbittlich in ihrem Streben nach Frieden oder ihrem Hass auf die Lebenden.", "Medien überbrücken die Kluft zwischen Geister- und Sterblichenwelt und fungieren als Mittler für jene, die ätherische Kreaturen um einen schrecklichen Gefallen bitten müssen. Das kann ein einträglicher oder selbstloser Beruf sein, ist aber immer gefährlich, denn selbst die friedlichsten Geister können schnell bösartig werden, wenn man sie erzürnt."], "p": 61}, {"id": "hor_okk", "n": "Okkultist", "s": ["HOR"], "req": "Verstand W6+", "f": "Zaubern (Verstand)", "sm": "Arkanes entdecken/verbergen, Aufheben, Verriegeln/Entriegeln und zwei weitere Mächte aus der Liste", "mp": "10", "av": ["Arkaner Schutz", "Verbannen", "Barriere", "Tierfreund", "Flächenschlag", "Blenden", "Geschoss", "Eigenschaft erhöhen/senken", "Strahl", "Verwirrung", "Leichensinn", "Fluch", "Schadensfeld", "Dunkelsicht", "Abwehren", "Arkanes entdecken/verbergen", "Verkleiden", "Aufheben", "Zwiesprache", "Machtpunkte entziehen", "Elementarmanipulation", "Empathie", "Verstricken", "Schutz vor Naturgewalten", "Exorzismus", "Fernsicht", "Furcht", "Grabtuch", "Chaos", "Illusion", "Unberührbarkeit", "Unsichtbarkeit", "Licht/Dunkelheit", "Orten", "Verriegeln/Entriegeln", "Albträume", "Objekt auslesen", "Schutz", "Marionette", "Zuflucht", "Fernschau", "Seance", "Trägheit/Beschleunigung", "Schlummer", "Waffe verbessern", "Geräusch/Stille", "Sprachen sprechen", "Rachsucht", "Betäuben", "Verbündeten beschwören", "Dämon beschwören", "Verwandlung unterdrücken", "Telekinese", "Teleportation", "Wandkrabbler", "Kriegersegen", "Zombie"], "sp": [["Magie", "Okkultisten dürfen Talente nehmen, die den Arkanen Hintergrund (Magie) voraussetzen."], ["Verderbnis", "Okkultisten spielen mit dunklen Kräften. Sie haben das Handicap Verderbnis (S. 6)."]], "b": ["Wissen ist Macht und gelegentlich der Pfad in den Wahnsinn. Okkultisten ergründen alle Arten arkanen Wissens: von Numerologie über Dämonenbeschwörung bis zu uralten Beschwörungsformeln. Sie studieren Berichte über Monster, Geister, Gespenster und Schrecken jeder Kultur der Erde – und einiger darüber hinaus!"], "p": 63}, {"id": "hor_prie", "n": "Priester", "s": ["HOR"], "req": "Willenskraft W6+", "f": "Glaube (Willenskraft)", "sm": "Heilung, Zuflucht und drei weitere Mächte aus der Liste", "mp": "10", "av": ["Arkaner Schutz", "Verbannen", "Barriere", "Tierfreund", "Eigenschaft erhöhen/senken", "Verwirrung", "Boden weihen", "Dunkelsicht", "Abwehren", "Arkanes entdecken/verbergen", "Aufheben", "Zwiesprache", "Empathie", "Verstricken", "Schutz vor Naturgewalten", "Exorzismus", "Fernsicht", "Chaos", "Heilung", "Licht/Dunkelheit", "Schutz", "Linderung", "Wiederauferstehung", "Zuflucht", "Fernschau", "Trägheit/Beschleunigung", "Schlummer", "Waffe verbessern", "Geräusch/Stille", "Sprachen sprechen", "Betäuben", "Kriegersegen"], "sp": [["Wunder", "Priester dürfen Talente nehmen, die den Arkanen Hintergrund (Wunder) voraussetzen."], ["Heiliges Symbol", "Priester, die das Symbol ihrer Religion deutlich sichtbar zeigen, erhalten einen kostenlosen Wiederholungswurf auf alle Glaubenwürfe."], ["Schwur", "Priester müssen einen Schwur (schwer) haben, ihrer Religion und deren Menschen zu dienen. Wenn sie die Werte ihrer Religion nicht einhalten, ziehen sie eine Woche lang 2 von Glaubenwürfen ab. Wirklich frevelhafte Taten können ihnen die Kräfte ganz rauben, bis sie auf irgendeine Weise Buße tun."]], "b": ["Priester sind Prediger, Imame, Rabbiner oder andere heilige Männer und Frauen, die von ihrer Religion geweiht wurden. Sie sind Beschützer der Menschheit und der von ihrem Schöpfer erschaffenen Welt. Die meisten befolgen zumindest die Kerngrundsätze ihrer Kirche, manche meiden aber die organisierte Religion für ihre eigene Art von Dienst."], "p": 64}, {"id": "hor_psyc", "n": "Psychischer Ermittler", "s": ["HOR"], "req": "Verstand W6+", "f": "Psionik (Verstand)", "sm": "Drei beliebige aus der Liste", "mp": "10", "av": ["Tierfreund", "Blenden", "Eigenschaft erhöhen/senken", "Verwirrung", "Fluch", "Zwiesprache", "Empathie", "Furcht", "Trugschrecken", "Gedankenverbindung", "Gedankenlesen", "Gedankenleere", "Orten", "Objekt auslesen", "Marionette", "Fernschau", "Schlummer", "Geräusch/Stille", "Verwandlung unterdrücken"], "sp": [["Psionik", "Psychische Ermittler dürfen Talente nehmen, die den Arkanen Hintergrund (Psionik) voraussetzen."]], "b": ["Die Gedanken der Schuldigen sind offene Bücher für jene, die Gedanken lesen können. Sie sind die ultimativen Spürnasen und können mit Konzentration Wahrheit von Lüge unterscheiden. Ob jemand ihren Lesungen glaubt, hängt von der Natur der Welt ab, in der sie leben – aber das ist der Preis für eine so aufdringliche Macht."], "p": 65}, {"id": "hor_vood", "n": "Voodoo-Priester", "s": ["HOR"], "req": "Willenskraft W6+", "f": "Glaube (Willenskraft)", "sm": "Zwei aus der Liste", "mp": "15", "av": ["Arkaner Schutz", "Aspekt des Rada-Loa", "Verbannen", "Barriere", "Tierfreund", "Blenden", "Eigenschaft erhöhen/senken", "Verwirrung", "Boden weihen", "Leichensinn", "Fluch", "Dunkelsicht", "Abwehren", "Arkanes entdecken/verbergen", "Aufheben", "Zwiesprache", "Empathie", "Exorzismus", "Furcht", "Zorn des Petro-Loa", "Chaos", "Heilung", "Trugschrecken", "Orten", "Albträume", "Objekt auslesen", "Schutz", "Marionette", "Linderung", "Zuflucht", "Seance", "Trägheit/Beschleunigung", "Waffe verbessern", "Sprachen sprechen", "Betäuben", "Kriegersegen", "Zombie"], "sp": [["Wunder", "Voodoo-Priester dürfen Talente nehmen, die den Arkanen Hintergrund (Wunder) voraussetzen."], ["Gris-Gris", "Voodoo-Priester müssen einen „Conjure“-Beutel am Körper tragen, um ihre Mächte zu aktivieren. Sie haben das Handicap Materialkomponenten (S. 7)."]], "b": ["Wer Voodoo praktiziert, sind Houngans (männlich) und Mambos (weiblich) – zusammen „Voodoo-Priester“. Ihre Macht kommt von Geistern namens „Loas“, einer Schar von Geistern mit bestimmten Persönlichkeiten und Eigenschaften wie Baron Samedi (Loa der Toten, der Zylinder, schwarzen Frack und dunkle Brille trägt), Papa Legba (Mittler der Geisterwelt, der als alter Mann mit Stock und Strohhut erscheint) oder die schreckliche Marinette Bwa Chech (ein gewalttätiger Geist, der ihr Volk aus der Knechtschaft befreit).", "Sanfte Geister sind Rada-Loas. Hitzköpfige Geister sind Petro-Loas. Manche bezeichnen Rada als „gute“ und Petro als „böse“ Geister, aber Voodoo-Priester sehen jeden Geist als Werkzeug. Manche haben relativ friedliche Zwecke, wie Legba. Andere sind gewalttätig, aber allzu oft nötig, wie Marinette.", "Voodoo-Priester verhandeln und verständigen sich mit ihren Geistern durch Rituale und Schreine. Sesshafte Houngans und Mambos haben Schreine für zahlreiche Loas in ihrem Haus oder in der Nähe. Reisende Voodoo-Priester behelfen sich mit einem kleinen Schrein, meist von Kerzen beleuchtet und jede Nacht vor ihnen aufgestellt, bevor sie sich schlafen legen. Beide verbringen täglich mindestens eine Stunde mit Gebet und gelegentlichen Tieropfern (die meist auch als Mahlzeit verzehrt werden).", "Diese Gebete und Rituale erbitten von verschiedenen Loas Macht, die in Talismane gebündelt wird – Steine, Knochen, Skulpturen, Tierteile oder sogar Dreck oder Staub von einem besonderen Ort. All das kommt in den „Gris-Gris“-Beutel des Voodoo-Priesters, damit er darauf zurückgreifen kann, wenn der Houngan oder die Mambo die Macht des Loas anruft. Will ein Houngan die Macht eines Loas anrufen, benutzt er als Aktion einen Talisman, schleudert einen Knochen als Angriff, reibt einen Katzenzahn zum Schutz und so weiter.", "Voodoo-Priester haben eine relativ kleine Auswahl an Mächten im Vergleich zu den meisten Arkanen Hintergründen, gleichen das aber durch zwei mächtige und vielseitige Zauber aus, die den Loa in ihren Körper einladen: Aspekt des Rada-Loa und Zorn des Petro-Loa."], "p": 66}, {"id": "hor_hexe", "n": "Hexenmeister/Hexe (Horror)", "s": ["HOR"], "req": "Verstand W6+", "f": "Zaubern (Verstand)", "sm": "Drei beliebige aus der Liste", "mp": "10", "av": ["Arkaner Schutz", "Verbannen", "Barriere", "Tierfreund", "Flächenschlag", "Blenden", "Geschoss", "Eigenschaft erhöhen/senken", "Graben", "Strahl", "Verwirrung", "Leichensinn", "Fluch", "Dunkelsicht", "Abwehren", "Arkanes entdecken/verbergen", "Verkleiden", "Aufheben", "Zwiesprache", "Machtpunkte entziehen", "Elementarmanipulation", "Empathie", "Verstricken", "Schutz vor Naturgewalten", "Exorzismus", "Fernsicht", "Furcht", "Fliegen", "Grabtuch", "Wachsen/Schrumpfen", "Chaos", "Heilung", "Illusion", "Trugschrecken", "Unsichtbarkeit", "Licht/Dunkelheit", "Orten", "Verriegeln/Entriegeln", "Gedankenlesen", "Gedankenleere", "Albträume", "Objekt auslesen", "Schutz", "Marionette", "Linderung", "Fernschau", "Seance", "Gestaltwandeln", "Trägheit/Beschleunigung", "Schlummer", "Waffe verbessern", "Geräusch/Stille", "Sprachen sprechen", "Rachsucht", "Betäuben", "Verbündeten beschwören", "Dämon beschwören", "Verwandlung unterdrücken", "Telekinese", "Wandkrabbler", "Kriegersegen"], "sp": [["Magie", "Hexenmeister und Hexen dürfen Talente nehmen, die den Arkanen Hintergrund (Magie) voraussetzen."], ["Komponenten", "Hexen und Hexenmeister brauchen allerlei Krimskrams für ihre Zauber, vom Molchsauge bis zum Haar eines Gehenkten, den sie in ihren „Hexenbeuteln“ aufbewahren. Sie haben das Handicap Materialkomponenten (S. 7)."], ["Verderbnis", "Hexenmeister und Hexen sammeln Macht und Wissen aus verschiedenen Quellen, von denen manche Körper und Geist ruinieren. Sie haben das Handicap Verderbnis (S. 6)."], ["Vertrauter", "Hexenmeister und Hexen halten ihre Verbindung zur natürlichen Welt über kleine magische Haustiere aufrecht. Sie beginnen mit einem Vertrauten (S. 69)."]], "b": ["Im Horrorgenre lernen Hexenmeister und Hexen ihr Handwerk aus alten Büchern oder von geheimnisvollen Mentoren und wenden sich nur in der größten Not dunklen Mächten zu. Der Großteil ihrer Magie konzentriert sich auf Herd und Heim, aber wer sie verärgert, merkt schnell, dass sie auch weit zornigere Zauber kennen.", "Hexenmeister und Hexen sind in historischen Settings, in denen Einheimische ihre magischen Kräfte fürchten, meist verschwiegen. In modernen Kampagnen oder Welten, in denen Magie üblich ist, können sie offener auftreten.", "Hinweis: Dieser Arkane Hintergrund unterscheidet sich von der Version im Savage Worlds Fantasy Companion."], "p": 68}]);
H.add([{"n": "Aspekt des Rada-Loa", "r": 0, "mp": "5", "rw": "Selbst", "wd": "eine Stunde", "au": "", "b": ["Diese Macht lädt einen Rada-Loa ein, den Körper des Houngans oder der Mambo bis zu eine Stunde lang zu „reiten“. Nur ein Geist darf gleichzeitig den Voodoo-Priester reiten, doch der Wirker darf den Zauber jederzeit fallen lassen und einen anderen beginnen.", "Aspekt des Rada-Loa lädt den Geist in ihren Körper ein und verleiht ihr einen Teil seiner Persönlichkeit (bei jeder Macht vermerkt). Dieser Loa bleibt für die gesamte Wirkungsdauer, und kein anderer Loa darf eingeladen werden, bis der vorherige Geist gegangen ist."], "m": [], "s": ["HOR"], "p": 71, "k": [{"h": "Agwé", "b": ["Dieser Loa herrscht über die großen Gewässer und alles, was darin lebt. Er wird meist als großer, gutaussehender Mann mit tiefgrünen Augen in formeller Kleidung dargestellt, der salzige Tränen für die über den Ozean verschleppten Sklaven des transatlantischen Sklavenhandels weint. Von Agwé Gerittene sind schwermütig und leicht zu Tränen gerührt.", "Der Zauber verleiht dem Voodoo-Priester Herrschaft über das Wasser für die Wirkungsdauer der Macht. Sie kann darauf gehen, unter der Oberfläche atmen und mit voller Bewegungsweite schwimmen (plus Laufwürfel, wenn gewünscht). Mit einer Steigerung addiert sie jede Runde +2 auf ihre Gesamtbewegungsweite."]}, {"h": "Baron Samedi", "b": ["Samedi erscheint als großer Mann mit schwarzem Hut, dunkler Brille, formellem Frack, Wattepfropfen in der Nase und bemaltem Totenkopfgesicht. Er ist ein schmutzigdenkender, flucherfüllter Loa, der menschliche Laster genießt. Samedi ist der Loa der Toten und Torwächter des Jenseits. Wer vom Baron besessen ist, wird derb und lüstern.", "Samedi trennt vorübergehend die Verbindung einer untoten Kreatur zur Geisterwelt. Bewegt sich eine Kreatur mit der Sonderfähigkeit Untot neben den Voodoo-Priester, muss sie eine Konstitutionsprobe ablegen (mit –2, wenn mit einer Steigerung gewirkt) oder wird Betäubt."]}, {"h": "Damballa", "b": ["Der uralte Schöpfer der Welt lag einst in Schlangengestalt unter der Erde. Er schuf die Berge, den Himmel, die Meere und alles, was die Menschheit sieht. Er ist ein mächtiger, makelloser Loa, der Botschaften von Reichtum, Wohlstand und Gesundheit durch Träume übermittelt. Wirker, die Damballa in ihren Körper einladen, werden geduldiger und freundlicher, mit einem langen Blick auf den Kosmos und alle, die darin leben.", "Du darfst für die Wirkungsdauer des Zaubers jeden Konstitutionswurf wiederholen. Wenn du die Reichtumsregeln aus Savage Worlds verwendest, darfst du auch jeden Reichtumswurf für die Wirkungsdauer wiederholen. Falls nicht, wiederhole jeden Überredenwurf, um zu feilschen oder anderweitig Preise zu verhandeln, um ein besseres Geschäft zu machen (ein Nachlass, den die SL für die jeweilige Situation für angemessen hält). Alle Würfe erhalten +1, wenn der Zauber mit einer Steigerung gewirkt wurde."]}, {"h": "Erzulie Fréda", "b": ["Erzulie erscheint als „schwarze Madonna“, ein Loa der Liebe und Weiblichkeit. Sie ist schön und freundlich, aber auch jähzornig. Wenn der Voodoo-Priester von Erzulie geritten wird, nimmt er diese Eigenschaften an.", "Der Held gewinnt Gunst, indem er (Haut auf Haut) eine einzelne Person berührt, die romantisch zu ihm hingezogen ist und mit einer Neutralen oder besseren Reaktion beginnt (Entscheidung der SL). Das ist nicht die Macht Marionette – die Person ist kein gedankenkontrollierter Sklave, sondern nur eifrig bemüht, dem Wirker zu gefallen. Eine Steigerung bedeutet, dass das Ziel noch eifriger hilft.", "Sobald die Macht endet, überdenkt das Ziel je nach Situation vielleicht sein Engagement. Natürlich kann der Voodoo-Priester Erzulie Fréda jederzeit wieder anrufen und die Beziehung neu entfachen."]}, {"h": "Papa Legba", "b": ["Legba ist der große Kommunikator. Er wird als alter Mann mit Stock, breitkrempigem Strohhut und Pfeife dargestellt und oft von einem treuen Hund begleitet. Wenn er jemanden reitet, wird dieser geduldiger, weiser und mitfühlender.", "Der Houngan oder die Mambo erhält für die Dauer der Besessenheit einen kostenlosen Wiederholungswurf auf alle Überreden-, Einschüchtern- oder Provozieren-Tests (mit +1, wenn mit einer Steigerung gewirkt)."]}]}, {"n": "Boden weihen", "r": 1, "mp": "5", "rw": "Berührung", "wd": "eine Stunde", "au": "Kreis aus Weihwasser oder Salz, Energiebarriere, Pentagramm", "b": ["Dieser Zauber verwandelt ein Stück Boden von der Größe einer Großen Flächenschablone in geweihten Boden (wie auf S. 41 beschrieben). Er braucht eine volle Minute Vorbereitung und irgendein Material (Salz, Kreide usw., je nach Ausprägung) zur Aktivierung, hält eine Stunde und kann danach aufrechterhalten werden.", "Übernatürlich gute Wesen schöpfen Kraft aus geweihtem Boden – sie erhalten dort +2 Robustheit. Übernatürlich böse Kreaturen sind Abgelenkt und Verwundbar, solange sie das geweihte Gebiet berühren. Mit einer Steigerung beim Zauber erleiden böse Wesen in Kontakt mit der Schablone am Ende ihres Zugs außerdem 2W4 Schaden.", "Hinweis: Böse Wirker können diese Macht anrufen, um entweihten Boden zu erschaffen."], "m": [["DAUER", "+5", "Muss als Ritual gewirkt werden. Die Wirkungsdauer verlängert sich bis zum nächsten Sonnenuntergang."]], "s": ["HOR"], "p": 73}, {"n": "Leichensinn", "r": 0, "mp": "2", "rw": "Selbst", "wd": "30 Minuten", "au": "Gesang, Starren in einen Spiegel", "b": ["Diese Beschwörung erlaubt dem Wirker, alle Leichen (einschließlich Untoter) der Größe Winzig oder größer innerhalb einer Meile (fünf mit einer Steigerung) aufzuspüren. Sobald sie entdeckt sind, kann der Wirker auch durch ihre Schädel sehen und hören, sofern sie einen haben.", "Empfindungsfähige Untote dürfen jede Runde als begrenzte Aktion eine Willenskraftprobe ablegen, um den Magier aus ihrem Geist zu werfen."], "m": [["SPRECHEN", "+1", "Der Wirker kann durch beliebige oder alle nicht animierten Schädel oder geistlosen Untoten sprechen."]], "s": ["HOR"], "p": 73}, {"n": "Exorzismus", "r": 2, "mp": "Speziell", "rw": "Verstand", "wd": "dauerhaft", "au": "Heilige Gegenstände, arkane Symbole, eine Handvoll Salz, weitere Ausprägungen passend zur auszutreibenden Kreatur", "b": ["Verbannen befreit die Sterblichenwelt vorübergehend von lästigen Geistern, aber solche Wesen dauerhaft zu verbannen erfordert mächtigere Magie. Exorzismus darf nur als Ritual gewirkt werden und wirkt nur auf Geister wie Dämonen, Gespenster oder ähnliche außerweltliche Wesen (Entscheidung der SL). Das schließt Wesenheiten ein, die einen sterblichen Wirt besessen haben.", "Jede Runde des Rituals ist ein vergleichender Wurf der arkanen Fertigkeit des Wirkers gegen die Willenskraft der Kreatur. Ist die Wesenheit in einem Bannkreis gefangen, darf der Wirker den Bonus des Kreises auf seine Würfe addieren. Natürlich ist es klug, sich beim Exorzieren mächtiger Wesen vorzubereiten – ein Aufwendiger Bannkreis und einige Verbündete zur Unterstützung sind entscheidend, wenn man sich mit mächtigen Kreaturen der Unterwelt anlegt!", "Misslingt das Ritual, werden die Komponenten des Wirkers zerstört, aber er darf es erneut versuchen, sobald neue Komponenten gesammelt sind. Ist er erfolgreich, wird die Wesenheit dauerhaft auf ihre Heimatebene zurückgeschickt (oder zerstört, Entscheidung der SL). Bestimmte kluge oder mächtige Wesen finden vielleicht irgendwann zurück in die Sterblichenwelt, aber das sollte ein seltener und schwieriger Vorgang sein.", "Die Machtpunktkosten betragen 3 plus den Willenskraftwürfel des Ziels, wenn es ein Wildcard ist, oder 3 plus den halben Willenskraftwürfel, wenn es eine Nebenfigur ist. Das Exorzieren eines Wildcard-Dämons mit Willenskraft W8 kostet zum Beispiel 11 Machtpunkte."], "m": [["UNSICHTBARER FEIND", "+4", "Ein Charakter darf einen Geist exorzieren, den er nicht sehen kann, solange er seinen ungefähren Aufenthaltsort kennt (ein kleines Haus, ein Stockwerk eines großen Hauses usw.) oder Kontakt zu einem Objekt oder einer Person hat, an die er gebunden ist. Das ist praktisch, wenn ein Haus heimgesucht wird, der Geist aber Gefahr spürt und sich vor Geisterjägern versteckt, oder wenn sich ein Dämon im Reich der Unterwelt verbirgt und einen Unglücklichen durch Mächte oder andere Manipulationen statt durch direkte Manifestation quält."]], "s": ["HOR"], "p": 74}, {"n": "Zorn des Petro-Loa", "r": 0, "mp": "5", "rw": "Selbst", "wd": "5", "au": "", "b": ["Petro-Loas sind aggressiver oder übellauniger als Rada-Loas, daher sind sie vor allem in gefährlichen Situationen wie Kämpfen nützlich. Wie Aspekt des Rada-Loa lädt Zorn des Petro-Loa diese Geister in den Körper des Voodoo-Priesters ein. Nur ein Geist darf gleichzeitig den Voodoo-Priester reiten, doch der Wirker darf den Zauber jederzeit fallen lassen und einen anderen beginnen.", "Andere Aspekte: Die meisten Loas haben mehr als einen Aspekt. Die hier aufgeführten sind die häufigsten Gefallen, um die heldenhafte Voodoo-Priester bitten."], "m": [], "s": ["HOR"], "p": 74, "k": [{"h": "Erzulie Dantor", "b": ["Erzulie Dantor ist ein Aspekt von Erzulie Fréda, geboren aus der blutigen Haitianischen Revolution. Sie erscheint als schwarze Madonna mit einer Narbe auf der Wange und einer abgeschnittenen Zunge – herausgeschnitten, damit sie die Geheimnisse der Revolution bewahrte. Wer von Erzulie geritten wird, erhält einen blutenden Schnitt auf der Zunge (ohne Spielwirkung) und für die Wirkungsdauer der Macht das Handicap Rachsüchtig (leicht).", "Die furchterregende Dantor ist eine rachsüchtige Beschützerin. Wer dem Voodoo-Priester schadet (ihn Angeschlagen, Betäubt oder Verwundet macht), muss sofort eine Willenskraftprobe ablegen (mit –2, wenn mit einer Steigerung gewirkt) oder wird Betäubt.", "Ziele von Erzulies Zorn sehen ihr geisterhaftes Antlitz aus dem Voodoo-Priester hervortreten. Sie rast auf sie zu, kreischt mit dem Stumpf ihrer abgeschnittenen Zunge, die Augen nachtschwarz und die blutbefleckten Hände nach Rache ausgestreckt. Sie fährt durch ihre Gestalt und kühlt sie bis ins Mark … dann verschwindet sie."]}, {"h": "Marinette Bwa Chech („Marinette der Trockenen Arme“)", "b": ["Dieser furchterregende Petro-Loa ist eine große, fast skelettartige Gestalt mit wildem Haar, wahnsinnigen Augen und ausgedörrter Haut in zerlumpten, blutbefleckten Kleidern. Von Marinette Gerittene erhalten das Handicap Gemein.", "Marinette erweitert die Nahkampfangriffe ihres Wirts auf Reichweite 2 und Stä+W6, DB 2, wenn unbewaffnet. Der Schaden steigt auf Stä+W8, wenn mit einer Steigerung gewirkt.", "Wer vom Voodoo-Priester getroffen wird, sieht ein geisterhaftes Bild der schrecklichen Marinette über den Angreifer gelegt, die in ihrer wahnsinnigen Wut Obszönitäten schreit und mit ihren schrecklichen trockenen Armen und langen, gezackten Klauen nach ihm greift."]}, {"h": "Met Kalfu", "b": ["Kalfu ist die dunkle Seite von Papa Legba. Er erscheint als eleganter Mann mit Zylinder und gespaltener Zunge. Er ist ein weiterer Loa der Kreuzung zwischen den Welten, mit Einfluss auf dunkle Geister und Gefühle. Wer Kalfu anruft, erhält das Handicap Skrupellos (leicht). Voodoo-Priester, die das Handicap bereits haben, erleiden den Abzug von –2 auf den Willenskraftwurf unten nicht.", "Als Meister seltsamer, spiritueller Energien kann Kalfu die Verbindung eines Ziels zum Schicksal selbst durchtrennen. Jedes Mal, wenn ein Feind innerhalb von 12“ (24 Metern) einen Benny ausgibt und der Voodoo-Priester das verhindern will, darf er einen Willenskraftwurf mit –2 ablegen (ohne Abzug, wenn mit einer Steigerung gewirkt). Bei Erfolg kann für diesen Wurf kein Benny ausgegeben werden. Mit einer Steigerung geht der Benny sogar verloren!", "Wird das Glück eines Gegners gekontert, sieht er ein geisterhaftes Bild von Kalfu, der gierig die Energie in seinen Mund zieht und sie voller Freude verschlingt."]}]}, {"n": "Grabtuch", "r": 1, "mp": "2", "rw": "Verstand", "wd": "10 Minuten", "au": "Blut, faules Fleisch, Müll", "b": ["Grabtuch verwandelt Aussehen und „Aura“ des Ziels in die eines Zombies. Es ist Verkleiden sehr ähnlich, aber die Illusion ist auf schlurfende Untote beschränkt und deckt auch Geruch und allgemeine „Aura“ solcher Kreaturen ab.", "Unwillige Opfer können mit einem vergleichenden Wurf der arkanen Fertigkeit gegen ihre Willenskraft anvisiert werden. Betroffene sehen aus und riechen wie eine wandelnde Leiche. Fast geistlose Untote (etwa Zombies und Skelette) behandeln das Ziel wie einen der Ihren. Intelligente Untote (etwa Vampire) halten den Charakter wahrscheinlich für einen geistlosen Diener, solange sie keinen Grund haben, genauer hinzusehen. Dann entdeckt eine Wahrnehmungsprobe mit –2 (–4, wenn mit einer Steigerung gewirkt) die Wahrheit und hebt die Illusion auf.", "In jedem Fall wehren sich Kreaturen, die vom „Untoten“ angegriffen werden, und schlagen entsprechend der Situation zurück."], "m": [["ZUSÄTZLICHE EMPFÄNGER", "+1", "Die Macht kann für je 1 zusätzlichen Machtpunkt mehr als ein Ziel beeinflussen."]], "s": ["HOR"], "p": 75}, {"n": "Trugschrecken", "r": 1, "mp": "5", "rw": "Verstand", "wd": "ein Tag", "au": "Der böse Blick, Spucke, ein persönlicher Besitz des Verfluchten wird gestohlen, jemanden dazu bringen, einen verfluchten Gegenstand anzunehmen", "b": ["Der Fluch verdreht den Geist des Ziels, sodass es überall, wohin es blickt, Schrecken sieht. Die Wirkungen können subtil sein: Die Augen eines Gemäldes bewegen sich, um sie zu beobachten, eine vorbeiziehende Krähe krächzt ihren Namen, oder eine Waffe oder ein Werkzeug in der Hand des Opfers scheint mit Blut oder Eiter bedeckt.", "Die Wirkungen können auch dramatisch sein: Das Opfer sieht eine furchtbare Hexe in den Schatten, eine Schar Vögel stürzt herab, um nach ihm zu hacken, oder ein Video vom Tod des Helden erscheint auf einem Fernsehbildschirm.", "Die Wirkungen der Macht werden nach Laune der SL aktiviert oder jedes Mal, wenn das Spiel in Runden abläuft und die Karte des Opfers keine Bildkarte ist. Das macht sie für diese Runde Abgelenkt, beeinflusst aber vor allem ihr Verhalten. Die Vision könnte das Opfer in eine Falle „treiben“, es vor anderen hysterisch handeln lassen, es etwas fallen lassen und so weiter."], "m": [["ZUSÄTZLICHE EMPFÄNGER", "+2", "Die Macht kann für je 2 zusätzliche Machtpunkte mehr als ein Ziel beeinflussen."]], "s": ["HOR"], "p": 75}, {"n": "Albträume", "r": 0, "mp": "2", "rw": "unbegrenzt", "wd": "eine Woche", "au": "", "b": ["Dieser hinterhältige Zauber lässt das Opfer schreckliche Albträume erleiden. Der Wirker muss den Namen des Opfers kennen und etwas besitzen, das ihm gehörte (etwa eine Haarlocke oder ein Kleidungsstück), muss aber nicht seinen genauen Aufenthaltsort kennen.", "Bei Erfolg hat das Opfer das Handicap Nachtschrecken (S. 7), bis es aufgehoben wird oder abläuft, der Wirker es beendet oder der Wirker getötet wird."], "m": [["BESTIMMTES THEMA", "+1", "Für 1 Machtpunkt kann der Wirker bestimmte Szenen oder Themen in die Albträume des Opfers pflanzen, vielleicht um es zu bestimmten Überzeugungen oder Handlungen zu drängen."]], "s": ["HOR"], "p": 76}, {"n": "Seance", "r": 1, "mp": "5", "rw": "Selbst", "wd": "speziell", "au": "Ouija-Bretter, persönliche Gegenstände des Geistes, Seancen", "b": ["Seance erlaubt es einem Wirker, mit verstorbenen Geistern zu sprechen. Der Zauber muss auf eine bestimmte Seele gerichtet werden, daher muss der Wirker entweder den Namen des Verstorbenen kennen oder einen persönlichen Gegenstand besitzen, der ihm gehörte, um die Seance zu versuchen.", "Gespenster, Spukgestalten, Poltergeister und Ähnliche haben einen sehr begrenzten Blick auf die körperliche Welt und ein noch geringeres Verständnis der ätherischen Sphäre. Sie verbringen die meiste Zeit in einem Zustand halber Bewusstheit und erhaschen nur gelegentlich Visionen der wirklichen Welt. „Gute“ Geister finden das friedlich und treten nur mit der Sterblichenwelt in Kontakt, wenn sie gewaltsam dorthin gerufen werden. Ruhelose Wesenheiten sehen das ganz anders. Sie blicken weit öfter in die Welt der Lebenden, suchen Erlösung von ihrem schrecklichen Leben und werden zu Wahnsinn und Gewalt getrieben. Sie versuchen aktiv, in die körperliche Sphäre zurückzukehren und ihre Wut an den dort gefundenen Lebewesen auszulassen.", "Ist das Ritual erfolgreich, manifestiert sich die Wesenheit lange genug, um drei Fragen nach bestem Wissen zu beantworten (mit einer Steigerung sind die Antworten genauer). Dann verblasst sie wieder im Nichts.", "Ein Kritischer Fehlschlag beim Wirken von Seance hat eine zusätzliche Folge – die Wesenheit (oder ein anderes Wesen, das vorgibt, die Wesenheit zu sein!) manifestiert sich in der Nähe! Was sie als Nächstes tut, hängt von ihrer Persönlichkeit ab, aber das Wesen muss gebunden und exorziert werden, um in das Geisterreich zurückzukehren."], "m": [["DÄMONISCHE PRÄSENZ", "+2", "Der Wirker kann mit anderen Wesenheiten des Geisterreichs sprechen, einschließlich Dämonen und Teufeln."], ["AUFGABE", "+2", "Geister sind keine Dämonen – sie haben keine Bedenken, zu verhandeln. Aber manchmal kann ein Beschwörer eine Wesenheit überzeugen, eine kleine Aufgabe auszuführen. Das Wesen wird wie oben beschrieben beschworen, aber statt Fragen gestellt zu bekommen, kann es gebeten werden, eine relativ einfache Aufgabe zu erledigen, die es in weniger als einer Stunde bewältigen kann."]], "s": ["HOR"], "p": 77, "k": [{"h": "Was wissen Geister?", "b": ["Das hängt weitgehend von der Wesenheit selbst ab. Geister haben im Wesentlichen einen „Tunnelblick“ auf die körperliche Welt, daher ist ihr Wissen meist auf ihre nähere Umgebung und Dinge beschränkt, die mit ihrer Natur oder Vergangenheit zu tun haben.", "Der Geist einer ermordeten Geliebten konzentriert sich wahrscheinlich ganz auf das Ereignis ihres Todes, wie sie ihrem Geliebten ihr Herz schenkte, wie der Diamant, den er ihr gab, in der Nacht funkelte, und wie sich später die Hände ihres Geliebten um ihren Hals schlossen, als er in eifersüchtige Wut geriet.", "Ein Junge, der bei einem tragischen Unfall starb, erinnert sich vielleicht an den roten Ball, den er die Treppe hinaufwarf, den Hund, der ihn überallhin begleitete, oder den Brunnen, in den er an einem glühend heißen Tag fiel.", "Mordopfer kennen nicht immer die Identität ihrer Mörder. Manchmal werden sie überrascht oder von hinten, aus der Ferne getötet, oder der Mörder trug eine Maske oder Verkleidung. Wenn die Macht Seance der Gruppe zur Verfügung steht, überlege, wie du verhinderst, dass sie das Rätsel verdirbt, ohne sie völlig nutzlos zu machen."]}]}, {"n": "Rachsucht", "r": 1, "mp": "3", "rw": "Selbst", "wd": "5", "au": "Eine schützende Wesenheit, schützende Runen auf der Haut, eine schwache rote Aura", "b": ["Gewalt zeugt Gewalt, besonders bei dieser rachsüchtigen Beschwörung. Immer wenn der Wirker durch einen direkten Angriff eine oder mehrere Wunden erleidet, erleidet der Angreifer 1W6 Schaden pro zugefügter Wunde. Wenn ein Okkultist eine Hexe mit Rachsucht für drei Wunden angreift, erleidet er danach 3W6 Schaden.", "Rachsucht löst aus, wann immer jemand dem Wirker Verletzungen zufügt. Das schließt zum Beispiel Flächenzauber ein, aber nicht, wenn man sich selbst mit der Klinge eines Gegners ersticht."], "m": [], "s": ["HOR"], "p": 78}, {"n": "Dämon beschwören", "r": 2, "mp": "Speziell", "rw": "Verstand", "wd": "nicht länger als eine Woche", "au": "Pentagramme, schwarze Kerzen, Tieropfer", "b": ["Die meisten Helden würden nie danach streben, mit den Bewohnern der Hölle zu verkehren, aber gelegentlich kann so etwas in Verfolgung eines edleren Ziels nötig werden.", "Dämonen dürfen nur durch Ritualmagie (S. 72) beschworen werden und müssen in einem Bannkreis herbeigerufen werden (vor Beginn des Rituals vorbereitet, siehe S. 48).", "Jede Runde des Rituals ist ein vergleichender Wurf der arkanen Fertigkeit des Wirkers gegen die Willenskraft der Kreatur. Der Modifikator des Bannkreises gilt auch für den arkanen Wurf jeder Runde des Rituals.", "Die Machtpunktkosten betragen 3 plus den Willenskraftwürfel des Ziels, wenn es ein Wildcard ist, oder 3 plus den halben Willenskraftwürfel, wenn es eine Nebenfigur ist. Das Beschwören eines Wildcard-Dämons mit Willenskraft W8 kostet zum Beispiel 11 Machtpunkte.", "Misslingt das Ritual, wird kein Dämon beschworen. Ein Kritischer Fehlschlag in einer beliebigen Runde des Rituals bedeutet, dass der Dämon erscheint, aber nicht gebunden ist und meist einen blutigen Angriff auf seine Beschwörer startet!", "Ist das Ritual erfolgreich, erscheint der Dämon im Bannkreis und ist gebunden. Hat der Wirker in der letzten Runde des Rituals eine Steigerung erzielt, ist der Dämon in irgendeiner Weise mächtiger – er hat eine zusätzliche Wunde, ein Talent, eine wichtige Eigenschaftssteigerung oder eine andere Fähigkeit, die die SL für angemessen hält.", "Aufgaben: Einem gebundenen Dämon kann im Austausch für eine Aufgabe die Freiheit angeboten werden. Der Dämon muss die Aufgabe vernünftigerweise ausführen können, auch wenn sie wahrscheinlich zu seinem „Tod“ führt (was ihn normalerweise nur dorthin zurückschickt, woher er kam). Sobald der Dämon dem Handel zustimmt, muss der Beschwörer den Bannkreis brechen und ihn freilassen. Der Dämon ist nun an den Wirker gebunden – er kann dem Beschwörer nicht direkt schaden und muss versuchen, die Aufgabe nach bestem Können zu erfüllen (auch wenn er zusätzlichen Unfug anrichten kann, wenn er kann!).", "Verständigung: Dämonen sind (im Allgemeinen) nicht telepathisch. Wenn der Beschwörer die böse Wesenheit außer Sichtweite schicken will, gibt er ihr besser sehr genaue Anweisungen. Intelligente Dämonen können physische Ausrüstung erhalten (etwa Mobiltelefone oder Sender in modernen Settings), aber ob sie diese Werkzeuge tatsächlich benutzen, liegt ganz bei ihnen.", "Spezialisierte Dämonen: Manche Dämonen verlangen besondere Opfergaben oder Wissen (etwa ihren wahren Namen), können nur bestimmten Bitten zustimmen oder haben andere Bedingungen wie Wirkungsdauer oder Art der Kontrolle. Ein Rachedämon kann zum Beispiel nur beauftragt werden, auf irgendeine Weise Rache zu üben (der Schwarze Kutscher auf S. 107 ist ein Beispiel). Das liegt ganz bei der SL, dem Setting und der Beschreibung der Kreatur.", "Spezifische Dämonen beschwören: Die SL darf Spielern erlauben, einige oder alle Dämonen aus Kapitel Sechs mit der Macht Dämon beschwören zu rufen, vielleicht mit Recherche und einem Abenteuer, um die jeweils nötigen Ritualkomponenten zu entdecken. Denk darüber nach, bevor du es den Spielern erlaubst, denn manche der Kreaturen dort sind unglaublich mächtig. Natürlich sind solche Wesen tödlich, wenn sie falsch behandelt werden, und selbst die Demütigung einer erfolgreichen Beschwörung wird nicht vergessen – das Wesen sucht später vielleicht Rache, entweder persönlich oder durch seine Diener."], "m": [], "s": ["HOR"], "p": 80}, {"n": "Verwandlung unterdrücken", "r": 2, "mp": "3", "rw": "Berührung", "wd": "eine Nacht", "au": "Trank, auf den Körper gezeichnete Runen, ein Kreis aus Wolfswurz, Silbermünzen auf den Augen", "b": ["Wenige Flüche sind so schrecklich wie jene, die das Opfer in etwas anderes verwandeln – etwas Scheußliches. Die meisten Monsterjäger wissen, dass Lykanthropen sich bei Vollmond in ihre Tiergestalt verwandeln, aber auch andere Schrecken können sich verwandeln. Ein Unglücklicher findet sich vielleicht in einen gurgelnden Fischmenschen verwandelt, während ein anderer langsam zu einem abscheulichen fliegenähnlichen Wesen wird.", "Dieser seltene Zauber gibt diesen bedauernswerten Seelen die Gelegenheit, ihre Menschlichkeit zurückzugewinnen und das Tier in sich zu unterdrücken.", "Einmal gewirkt, widersteht ein Opfer, das mit Lykanthropie oder einer anderen verwandelnden Krankheit geschlagen ist, der Verwandlung oder hält ihren Fortschritt für die nächsten 24 Stunden an."], "m": [["DAUERHAFT", "+4", "Wird als Ritual (S. 72) gewirkt, wird das Opfer dauerhaft von dem Leiden geheilt, das es plagt. Das erfordert zusätzlich zur üblichen Zahl an Komponenten das Herz oder ein anderes lebenswichtiges Organ einer größeren Kreatur derselben Art, das verbraucht wird, ob das Ritual gelingt oder nicht."]], "s": ["HOR"], "p": 81}]);
H.reg([{"id": "hor_ritual", "t": "Ritualmagie (Horror)", "p": 70, "s": ["HOR"], "bl": [{"h": "Ritualmagie", "s": ["HOR"], "b": ["Magie ist in Horror-Settings selten und mächtig und oft darauf ausgelegt, einen ganz bestimmten Effekt zu erzielen, etwa einen interdimensionalen Riss zu versiegeln oder eine schreckliche Abscheulichkeit hindurch zurückzutreiben. Solche Zauber werden fast immer durch Rituale aktiviert.", "Rituale werden von Ermittlern meist in muffigen Folianten oder zerfallenden Grimoires entdeckt, in modernen Kampagnen vielleicht auch im Internet! Folge den Schritten unten, wenn die Gruppe Ritualmagie benötigt.", "• MACHT WÄHLEN: Der Wirker wählt eine beliebige Macht, die er kennt oder zu der er über Folianten, Schriftrollen, Grimoires und Ähnliches Zugang erhält (er muss sie nicht selbst kennen). Dann addiere ihre gesamten Machtpunkte, einschließlich Modifikatoren, Einschränkungen und Verbesserungen aus der Tabelle unten. Ritualmagie kostet eigentlich keine Machtpunkte, aber die Summe wird verwendet, um die Kosten in Komponenten zu bestimmen (siehe unten)."], "tab": {"c": ["Kosten", "Verbesserung des Ritualzaubers"], "r": [["3/5", "Erhöht die Wirkungsdauer einer in Runden angegebenen Macht auf Minuten für 3 Punkte oder auf eine Stunde für 5."], ["3/5", "Wenn eine Macht ein Wirkungsgebiet hat, kann es auf einen Radius von 50 Metern für +3 Punkte oder 100 Metern für +5 vergrößert werden. Beide Verbesserungen können sich auch an ein Gebäude, Schiff oder anderen unregelmäßigen Raum ungefähr derselben Größe anpassen (Entscheidung der SL)."], ["5", "Ziele der Macht widerstehen ihren Effekten mit einem zusätzlichen Modifikator von –2, zusätzlich zu allen Machtmodifikatoren wie Stark."]]}}, {"h": "Komponenten und Abzüge", "s": ["HOR"], "b": ["• KOMPONENTEN: Ritualmagie erfordert eine Anzahl Komponenten, die sich nach den gesamten Machtpunkten des Zaubers richtet. Die SL kann diese Komponenten selbst wählen oder zufällig auf den Komponententabellen auf den vorangehenden Seiten auswürfeln. Das Sammeln der Komponenten ist meist ein großer Teil eines Abenteuers und manchmal selbst ein Abenteuer."], "tab": {"c": ["Machtpunkte", "Gewöhnlich", "Exotisch", "Abzug beim Wirken"], "r": [["1–2", "2", "—", "–2"], ["3–4", "2", "1", "–2"], ["5–6", "3", "1", "–2"], ["7–8", "3", "2", "–3"], ["9–10", "4", "2", "–3"], ["11–12", "4", "3", "–3"], ["13–14", "5", "3", "–4"], ["15–16", "5", "4", "–4"], ["17–18", "6", "4", "–4"]]}, "z": "… und so weiter."}, {"h": "Vorbereitung und Wirken", "s": ["HOR"], "b": ["• VORBEREITUNG: Sobald die Komponenten gesammelt sind, verbringt der Magier zehn Minuten pro Rang des Zaubers mit stationärer Vorbereitung: Linien auf den Boden zeichnen, die Komponenten vorbereiten, verbrennen oder zerstören oder sich einfach konzentrieren. Ein Zauber des Ranges Anfänger braucht 10 Minuten Vorbereitung, eine Macht des Ranges Veteran eine halbe Stunde.", "• WIRKEN: Der Zauber wird mit der Fertigkeit Okkultismus über eine Schwierige Dramatische Aufgabe für eine Einzelperson aktiviert. Der Abzug beim Wirken hängt von den benötigten Machtpunkten ab (siehe Tabelle oben). Der Wirker nutzt seine Okkultismus- oder arkane Fertigkeit, wenn der Zauber seinem Arkanen Hintergrund zur Verfügung steht. Die Macht wird sofort mit dem erfolgreichen Abschluss der Dramatischen Aufgabe gewirkt. Das letzte Würfelergebnis der Aufgabe gilt als Wirkungsergebnis. Zauberwirker dürfen keine Machtpunkte ausgeben, um die Macht aufrechtzuerhalten. Misslingt die Dramatische Aufgabe, misslingt das Ritual und die Komponenten werden verbraucht. Dieser Wirker darf dasselbe Ritual eine Woche lang nicht erneut versuchen (andere schon).", "Ein Kritischer Fehlschlag beim letzten Wurf des Rituals hat neben den Folgen des Misslingens selbst eine zusätzliche Wirkung. Das könnte eine arkane Explosion in einer Großen Flächenschablone mit 3W6 Schaden sein, einer übernatürlichen Wesenheit den Eintritt in die Welt erlauben, die Körper der Beteiligten vertauschen oder was auch immer die SL für das jeweilige Setting, die Macht und die Umstände sinnvoll hält."]}, {"h": "Gewöhnliche Ritualkomponenten", "k": 1, "s": ["HOR"], "b": [], "tab": {"c": ["W20", "Komponente", "Beschreibung"], "r": [["1", "Tierteil", "Meist von einer kleineren Kreatur, die als Nahrung oder Haustier dient. Beispiele: Hühnerfuß, Schildkrötenfleisch, Rattenschwanz."], ["2", "Tierfetisch", "Erfordert nicht den Tod des Tiers, aber die Kreatur selbst ist meist groß, selten oder aggressiv. Beispiele: Stierschwanz, Straußenfeder, Schlangenhaut."], ["3", "Gefährliches Totem", "Meist der gefährlichste Teil eines aggressiven Tiers. Beispiele: Klapperschlangenrassel, Bärenkralle, Stinktierschwanz."], ["4", "Unglücksomen", "Leicht zu beschaffen, gilt aber als Pech. Beispiel: Eine Scherbe eines zerbrochenen Spiegels, verschüttetes Salz, eine geschenkte Uhr."], ["5", "Menschlicher Abfall", "Unangenehmer Abfall, der von einem Menschen produziert wird. Beispiele: Erbrochenes, menschliches Blut, Fingernagelschnipsel."], ["6", "Giftiges Körperteil", "Ein Teil einer giftigen Kreatur oder das Gift selbst. Beispiele: Skorpionschwanz, Schlangengift."], ["7", "Pulvermischung", "Eine gepulverte Mischung mehrerer Chemikalien. Beispiele: Schießpulver, Salpeter."], ["8", "Bedeutungsvoller Gegenstand", "Etwas mit emotionaler oder spiritueller Bedeutung. Beispiele: Das Spielzeug eines Kindes, das Kreuz eines Gläubigen."], ["9", "Spezielle Flüssigkeit", "Eine Flasche mit etwas besonders Gebrautem oder Gesegnetem. Beispiele: Eine Flasche eines bestimmten Alkohols, Weihwasser, frisch gemolkene Milch (unpasteurisiert)."], ["10", "Eindringliches Souvenir", "Ein Gegenstand, für dessen Beschaffung man Privatsphäre oder Tabus verletzen muss. Beispiele: Luft aus einer versiegelten Gruft, ein Ziegel aus einem bewohnten Haus."], ["11", "Giftige Substanz", "Potenziell schädliche Chemikalien oder Verbindungen. Beispiele: Arsen, Asbest, Lachgas."], ["12", "Regionales Zeichen", "Ein Gegenstand, der eine bestimmte Art Land oder Klima repräsentiert. Beispiele: Strandsand, ein Tannenzapfen."], ["13", "Zeremonielle Speisen", "Nahrungsmittel, um die Geister zu erfreuen oder zu füttern. Beispiele: Besonders gebackenes Brot, eine Tüte Zucker."], ["14", "Reptilienteil", "Bestandteile verschiedener reptilienartiger Kreaturen. Beispiele: Das Auge einer Eidechse, die Haut eines Chamäleons, Schlangenschuppen."], ["15", "Ungezieferteil", "Bestandteile eines oder mehrerer Insekten. Beispiele: Die Beine einer Grille, ein Spinnennetz, vier Fliegenflügel."], ["16", "Tierzähne", "Ein oder mehrere Zähne einer bestimmten Kreatur. Beispiele: Der Zahn eines Kätzchens, der Zahn eines Hais."], ["17", "Tierinnereien", "Innere Organe oder Blut einer einzelnen oder mehrerer kleinerer Kreaturen. Beispiele: Ein Eimer Fischeingeweide, das Herz einer Kuh."], ["18", "Besonderes Glas", "Scherben oder Pulver aus einer bestimmten Glassorte. Beispiele: Zerstoßenes rotes Glas, ein Stück Glas aus einem zerbrochenen Kirchenfenster."], ["19", "Todessymbol", "Ein Gegenstand, der den Tod oder das Grab repräsentiert. Beispiele: Friedhofserde, ein Splitter eines 100 Jahre alten Grabsteins."], ["20", "Symbol des Verfalls", "Ein Gegenstand, der Altern oder Zerfall repräsentiert. Beispiele: Ein rostiges Scharnier, Balken eines eingestürzten Hauses."]]}}, {"h": "Exotische Ritualkomponenten", "k": 1, "s": ["HOR"], "b": [], "tab": {"c": ["W20", "Komponente", "Beschreibung"], "r": [["1", "Seltenes Haar", "Eine kleine Zahl Haarfollikel von einer bestimmten Art von Spender. Beispiele: Haarsträhnen einer 100 Jahre alten Frau, Haar aus einer Löwenmähne."], ["2", "Giftiges Tier", "Ein lebendes und potenziell gefährliches Exemplar, das als Teil der Vorbereitungen geopfert wird. Beispiele: Eine Kobra, eine lebende Klapperschlange."], ["3", "Radioaktives Material", "Natürlich vorkommende oder Abfallprodukte, die ohne Abschirmung gefährlich radioaktiv sind. Beispiele: 12 Unzen Radium, 2 Unzen Uran."], ["4", "Atypische Teile", "Organische Bestandteile, die von einem kranken oder ungewöhnlichen Exemplar gewonnen wurden. Beispiele: Das Gehirn eines tollwütigen Tiers, Fell einer Albinokatze."], ["5", "Seltenes Pulver", "Die zerstoßenen Überreste von etwas Teurem oder Ungewöhnlichem. Beispiele: Asche eines Waldbrands, Nashornpulver."], ["6", "Verfluchtes Totem", "Ein Gegenstand, der von dunkler Magie berührt wurde. Beispiele: Ein gebundener böser Geist, ein verfluchter Gegenstand."], ["7", "Menschliche Überreste", "Teile eines toten menschlichen Körpers. Beispiele: Gemahlene menschliche Knochen, eine Gallone Blut einer Person, ein Auge oder ein abgetrennter Finger."], ["8", "Natürliche Konstruktion", "Etwas, das in der Natur entstanden ist und gefunden und geborgen werden muss. Beispiele: Ein Falkennest, ein Tritonshorn."], ["9", "Edelmetall", "Eine teure Menge reinen Edelmetalls. Beispiele: 12 Unzen reines Silber, 2 Unzen massives Gold."], ["10", "Großes Tier", "Ein lebendes Exemplar muss als Teil der Vorbereitungen geopfert werden. Beispiele: Eine Kuh, ein Hirsch."], ["11", "Große Trophäen", "Die Knochen, Stoßzähne oder Hörner eines sehr großen Tiers. Beispiele: Ein Elefantenstoßzahn, ein Walknochen."], ["12", "Okkultes Zeichen", "Überreste eines makabren Wesens. Beispiele: Dämonenblut, Staub zerfallener Untoter."], ["13", "Symbol einer Emotion", "Ein Gegenstand, der ein extremes Gefühl repräsentiert. Beispiele: Die Träne eines Kindes, ein zurückgegebener Verlobungsring."], ["14", "Mordrelikt", "Ein Gegenstand, der an einem brutalen Mord beteiligt war. Beispiele: Der Ehering einer ermordeten Braut, die Mordwaffe eines Serienmörders."], ["15", "Seltene Steine", "Natürlich vorkommende Steine in unbearbeitetem Zustand. Beispiele: Unpolierter Jade, ein tiefer Flussstein."], ["16", "Uralte Flüssigkeiten", "Jede abgefüllte Substanz, die über 100 Jahre alt ist. Beispiele: Uralter Wein, Wasser, das länger als ein Jahrhundert gelagert wurde."], ["17", "Seltene Pflanzen", "Schwer zu findende oder spezialisierte Pflanzen. Beispiele: Nachtblühende Blumen, fleischfressende Pflanzen."], ["18", "Kristallisierte Objekte", "Jede natürlich entstehende Kristall- oder ähnliche Substanz. Beispiele: Versteinertes Baumharz (Bernstein), ein Rubin."], ["19", "Grausige Tierpräparate", "Scheußlich konservierte Körperteile von Tieren oder Menschen. Beispiele: Eine Gorillapfote, ein Schrumpfkopf."], ["20", "Heilige oder unheilige Reliquien", "Gegenstände, die von wahren Gläubigen verehrt werden. Beispiele: Das Grabtuch eines Heiligen, die Klinge eines berühmten Sünders."]]}}]}, {"id": "hor_vertraute", "t": "Vertraute", "p": 69, "s": ["HOR"], "bl": [{"h": "Vertraute", "s": ["HOR"], "b": ["„Vertraute“ sind kleine Kreaturen (Größe –2 oder –3), die als treue Haustiere und magische Gefährten eines Magiers dienen. Sie sind ihren Meistern treu, aber keine Sklaven. Sie sind sehr kluge Versionen ihrer Art, können aber gelegentlich durch ihre eigenen Instinkte abgelenkt werden. Eine Katze könnte ihre Aufgabe unterbrechen, um eine Maus zu jagen oder ein Nickerchen zu halten, und ein Hund wird fast sicher bellen, wenn sich ein Fremder nähert.", "Ein Vertrauter ist ein Wildcard, was Wunden und das Würfeln eines Wilden Würfels bei seinen Eigenschaftswürfen angeht. Er erhält keine Bennys, aber der Magier kann seine eigenen für ihn ausgeben.", "Der Vertraute versteht die Sprache seines Meisters und umgekehrt (andere hören nur die natürlichen Laute der Kreatur), wobei die Begriffe auf das beschränkt sind, was ein Mitglied seiner Art verstehen könnte.", "Der Vertraute hat 5 eigene Machtpunkte. Er kann keine Zauber wirken, aber der Magier kann sie wie seine eigenen verwenden. Sie laden sich getrennt und mit derselben Rate wie die des Magiers auf.", "Die Bindung zwischen Vertrautem und Magier macht ihn immun gegen die von anderen gewirkte Macht Tierfreund.", "Ein Vertrauter steigt nicht auf, sondern erhält für jeden Rang seines Meisters (einschließlich Anfänger) und für jeden vierten Aufstieg, den der Held über Legendär hinaus erhält, einen der folgenden Vorteile:", "• ZWEITES GESICHT: Der Besitzer darf die Sinne des Vertrauten wie seine eigenen nutzen, mit einer maximalen Reichweite von 10 Meilen. Er ist dabei Abgelenkt und Verwundbar.", "• TRAINING: Der Magier kann eine der Eigenschaften des Vertrauten um einen Würfeltyp erhöhen (nicht mehr als einmal pro Eigenschaft).", "• VERBESSERUNG: Der Vertraute erhält ein Talent. Es muss für die Art des Vertrauten sinnvoll sein (Entscheidung der SL) und die Voraussetzungen wie üblich erfüllen.", "Stirbt ein Vertrauter, ist der Held automatisch Betäubt (egal wie weit entfernt er ist). Er kann nach 10 Tagen einen neuen herbeirufen und die Art ändern, wenn er will."]}]}, {"id": "hor_hilfen", "t": "Hinweise zu Mächten (Horror)", "p": 73, "s": ["HOR"], "bl": [{"h": "Neue Mächte", "s": ["HOR"], "b": ["Auf den folgenden Seiten findest du eine Reihe von Mächten, die in vielen Horror-Settings vorkommen – etwa das Beschwören und Austreiben von Wesenheiten oder das Sprechen mit Leichen.", "Diese neuen Mächte, ebenso wie die aus Savage Worlds, funktionieren größtenteils normal, aber du solltest ihre Ausprägungen sorgfältig bedenken. Magie in Horror-Settings ist typischerweise dunkel und faustisch. Während Verstricken den Zauber gut zusammenfasst, hat die Bezeichnung „Tentakel von Vralkresh“ viel mehr Gewicht und Atmosphäre.", "Wenn Charaktere Magie nur aus Folianten lernen können, erwäge, Zaubern Namen zu geben, die nicht sofort verraten, was der Zauber tut. Magie ist keine Wissenschaft, die in Schulen gelehrt wird, und Magier geben ihren Zaubern selten nüchterne Namen. Engelsspeer könnte Geschoss sein, aber auch Niederstrecken oder Betäuben. Winde des Todes könnten leicht Flächenschlag, Explosion, Eigenschaft senken oder sogar eine feuerartige Barriere mit nekromantischer Ausprägung sein."]}, {"h": "Gut, Böse und das Übernatürliche", "k": 1, "s": ["HOR"], "b": ["Manche Mächte und Fähigkeiten verweisen auf „übernatürliche“ Kreaturen, Mächte und Wesen oder sogar auf „Gut“ und „Böse“. Aber was bedeutet das in Spielbegriffen?", "Die kurze Antwort lautet: Das hängt von der SL anhand von Setting und Wesen ab, aber hier einige Richtlinien.", "Alle Kreaturen, die ohne die Existenz des Übernatürlichen nicht existieren könnten, sind selbst übernatürlich: Zombies, Vampire, Geister, Dämonen usw. Zauberer, die Magie nutzen, sind nicht selbst übernatürlich, aber ihre Mächte sind es.", "„Gut“ bedeutet im Allgemeinen Wesen, die existieren, um die Menschheit zu beschützen. „Böse“ Wesen sind jene, die sie zerstören wollen. Ein Geist, der sein Haus gegen Eindringlinge heimsucht, ist nur böse, wenn er dauerhaften Schaden anrichten will. Ein Engel, der gegen Gott rebelliert, um den „Affen“, die die Erde erbten, Verderben zu bringen, ist übernatürlich und böse, auch wenn er göttlich geboren wurde."]}, {"h": "Zauberunterstützung für lange Aufgaben", "k": 1, "s": ["HOR"], "b": ["Zauber wie Eigenschaft erhöhen halten nur fünf Runden; wenig nützlich für etwas wie das Erhöhen von Überleben für einen Späher, der eine Expedition in die Berge des Wahnsinns führen soll.", "Für langfristige Aufgaben erlaube Zauberwirkern, ihre Mächte trotzdem einzusetzen, in der Annahme, dass sie in kritischen Momenten unterwegs Eigenschaften erhöhen, Linderung gewähren oder Schutz bieten können."]}]}]);
})();
